-- DA Ranch Vineyard App
-- 5 of 5. First vineyard, the 10 tasks, blocks, chemicals, and Non-field work.
-- Does not create a login. After Aaron signs up, run supabase/assign-developer.sql.

values (
  'DA Ranch', 'America/Phoenix', '14:25:00', 3,
  34.7183, -111.9086, 'https://www.wunderground.com/weather/us/az/cornville'
)
on conflict (name) do update
  set latitude = coalesce(public.vineyards.latitude, excluded.latitude),
      longitude = coalesce(public.vineyards.longitude, excluded.longitude),
      weather_url = coalesce(public.vineyards.weather_url, excluded.weather_url);

do $seed$
declare
  v_id uuid;
begin
  select id into v_id from public.vineyards where name = 'DA Ranch';
  perform private.seed_vineyard_defaults(v_id);

  update public.blocks
  set variety = 'Malvasia Bianca'
  where vineyard_id = v_id and name = 'DA Malvasia' and variety = 'Malvasia';

  update public.blocks
  set name = 'DA Greco de Tuffo', variety = 'Greco de Tuffo'
  where vineyard_id = v_id and name = 'DA Grecco De Tuffo';

  update public.blocks
  set variety = 'Teroldego'
  where vineyard_id = v_id and name = 'HM Toraldego' and variety = 'Toraldego';

  on conflict (vineyard_id, name) do nothing;

  on conflict (vineyard_id, name) do nothing;

  on conflict (vineyard_id, variety, text) do nothing;

  on conflict (vineyard_id, text) do nothing;

  update public.variety_notes
  set vigor = $q$This block is Malvasia Bianca. No vigor note was found for Malvasia Bianca. The Plantgrape index that was checked did not list it. VIVC passport 7256 identifies Malvasia Bianca as an Italian white, Sciaccarello × unknown, hermaphrodite. That passport is not field performance.$q$,
      arizona = $q$This block is Malvasia Bianca. The Verde Valley AVA FAQ names Malvasia Bianca. The 2016 survey recorded Malvasia Bianca at 5.27 acres, 4.2 percent of 124.6 acres. The 2025 University of Arizona harvest report included malvasia bianca among six varieties that were half of 532 acres. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$
  where vineyard_id = v_id and variety = 'Malvasia' and vigor like 'No vigor note was found%';

  update public.variety_notes
  set vigor = $q$This block is Greco de Tuffo. The earlier list spelled it Grecco De Tuffo. It is the Greco used for Greco di Tufo, from Campania. No vigor note was found. No Plantgrape field page was found for this name.$q$,
      arizona = $q$Greco de Tuffo was not on the Verde Valley AVA FAQ list that was checked, and no acreage for it was in the 2016 shares that were checked. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$
  where vineyard_id = v_id and variety = 'Greco' and vigor like 'No vigor note was found%';

  update public.variety_notes
  set vigor = $q$The grape's name is Teroldego. The block list spelled it Toraldego. Taraldego is not the name. No vigor note was found. VIVC passport 12371 identifies Teroldego as an Italian black wine grape. That passport is not field performance. No Plantgrape field page was found.$q$
  where vineyard_id = v_id and variety = 'Teroldego' and vigor like 'No vigor note was found%';

    vineyard_id, variety, needs_research, vigor, timing, clusters, pests, climate, arizona, harvest, canopy, sources
  )
  values
    (v_id, $q$Tannat$q$, false, $q$Fairly vigorous. It is usually pruned long, and it must be trellised.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 4 days after Chasselas. Maturity is mid-season, 3.5 weeks after Chasselas.$q$, $q$Bunches are large. Berries are small to medium.$q$, $q$Sensitive to mites and vine leafhoppers. A little susceptible to grey rot.$q$, $q$The catalogue describes powerful, full-bodied, age-worthy wines. It does not give a separate heat or drought score.$q$, $q$The Verde Valley AVA FAQ lists Tannat among the reds. The 2016 survey shares that were checked did not give a separate Tannat acreage. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. The catalogue says the wines are colored, very tannic, and lively, with a slightly harsh acidity.$q$, $q$Trellis it. Long pruning is the usual choice in the catalogue.$q$, $q$Plantgrape Tannat, plantgrape.fr/en/varieties/fruit-varieties/268. Verde Valley AVA FAQ. University of Arizona Cooperative Extension ClimateGem.$q$),
    (v_id, $q$Cabernet Sauvignon$q$, false, $q$Vigorous when fertile: large-diameter shoots, very long branches, long internodes, and lignified tendrils. Trellis it carefully. Pruning can be long or short in southern areas, and it is slow. Avoid large wounds. The hard wood is slow to remove. Published genetics: Cabernet franc × Sauvignon, from Bordeaux.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 13 days after Chasselas (late budburst). Maturity is mid-season, 3 to 3.5 weeks after Chasselas.$q$, $q$Bunches and berries are small.$q$, $q$Not very susceptible to grey rot. Very susceptible to wood diseases (eutypa and esca) and to powdery mildew. Stem dessication can show up, and it is worse on the SO4 rootstock.$q$, $q$Often better on gravelly, draining, rather acid, well-exposed ground. The catalogue does not give a drought score.$q$, $q$The Verde Valley AVA FAQ lists Cabernet Sauvignon. In the 2016 survey it was 11.40 acres, 9.1 percent of 124.6 acres. The 2025 University of Arizona harvest report ranked it third in acreage, after Syrah and Grenache. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. At proper maturity the catalogue describes an interesting tannic structure and deep color, suitable for ageing and wood. Vegetal aromas last until the fruit is ripe, and the wine alone often lacks body.$q$, $q$Careful trellising. In southern zones, long or short pruning. Avoid large pruning wounds.$q$, $q$Plantgrape Cabernet-Sauvignon, plantgrape.fr/en/varieties/fruit-varieties/43. Verde Valley AVA FAQ. 2016 Verde Valley vineyard survey. University of Arizona Cooperative Extension, ClimateGem and the 2025 harvest report.$q$),
    (v_id, $q$Tempranillo$q$, false, $q$Rather rustic and vigorous. Branches are brittle and sensitive to wind. Fertile enough to prune short, and it can alternate. Origin Rioja. Published genetics: Albillo Mayor × Benedicto.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 7 days after Chasselas. Maturity is mid-season, 2 weeks after Chasselas. It is early, so it can be grown in cooler zones and picked before equinox rains.$q$, $q$Bunches are large and elongated. Berries are medium.$q$, $q$Not very sensitive to grey rot. Especially susceptible to eutypa and vine leafhoppers.$q$, $q$Well adapted to southern conditions, but the branches are brittle in wind. In hot zones the wines lack acidity. The catalogue does not give a drought score.$q$, $q$Tempranillo was 4.65 acres, 3.7 percent, in the 2016 Verde Valley survey. The AVA FAQ list that was checked does not name it. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. On good sites the catalogue describes pleasant, well-colored, full wines that lack acidity in hot zones. Quality and alcohol drop quickly if yields are high.$q$, $q$Prune short, and protect the brittle shoots from wind.$q$, $q$Plantgrape Tempranillo, plantgrape.fr/en/varieties/fruit-varieties/269. 2016 Verde Valley vineyard survey. Verde Valley AVA FAQ. University of Arizona Cooperative Extension ClimateGem.$q$),
    (v_id, $q$Malvasia$q$, true, $q$This block is Malvasia Bianca. No vigor note was found for Malvasia Bianca. The Plantgrape index that was checked did not list it. VIVC passport 7256 identifies Malvasia Bianca as an Italian white, Sciaccarello × unknown, hermaphrodite. That passport is not field performance.$q$, $q$No budbreak or ripening timing was found for this name.$q$, $q$No cluster or berry description was found for this name.$q$, $q$No disease or pest rating was found for this name.$q$, $q$No heat or drought rating was found for this name.$q$, $q$This block is Malvasia Bianca. The Verde Valley AVA FAQ names Malvasia Bianca. The 2016 survey recorded Malvasia Bianca at 5.27 acres, 4.2 percent of 124.6 acres. The 2025 University of Arizona harvest report included malvasia bianca among six varieties that were half of 532 acres. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$No published Brix, pH, or titratable acidity was found. This block's own samples are the record.$q$, $q$No canopy note was found.$q$, $q$VIVC 7256 passport only. Verde Valley AVA FAQ. 2016 Verde Valley vineyard survey. University of Arizona Cooperative Extension ClimateGem and 2025 harvest report. Plantgrape index checked, no Malvasia page.$q$),
    (v_id, $q$Greco$q$, true, $q$This block is Greco de Tuffo. The earlier list spelled it Grecco De Tuffo. It is the Greco used for Greco di Tufo, from Campania. No vigor note was found. No Plantgrape field page was found for this name.$q$, $q$No budbreak or ripening timing was found.$q$, $q$No cluster or berry description was found.$q$, $q$No disease or pest rating was found.$q$, $q$No heat or drought rating was found.$q$, $q$Greco de Tuffo was not on the Verde Valley AVA FAQ list that was checked, and no acreage for it was in the 2016 shares that were checked. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$No published Brix, pH, or titratable acidity was found. This block's own samples are the record.$q$, $q$No canopy note was found.$q$, $q$No field catalogue page was found. Verde Valley AVA FAQ checked, Greco not listed. University of Arizona Cooperative Extension ClimateGem.$q$),
    (v_id, $q$Syrah$q$, false, $q$Long shoots are fragile in spring wind and must be trellised carefully. Short pruning is usually enough in southern zones. Sensitive to chlorosis and poorly adapted to high active limestone. Do not graft it on 110 R. Published genetics: Mondeuse blanche × Dureza. The origin seems to be the northern Côtes du Rhône or the Dauphiné.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 6 days after Chasselas. Maturity is mid-season, 2.5 weeks after Chasselas. It ripens quickly, with a short window from veraison to ripeness.$q$, $q$Bunches are small to medium. Berries are small.$q$, $q$Not very susceptible to downy mildew. Rather sensitive to mites and to grey rot late in ripening. A specific decline shows leaf reddening at the graft, and trunks can die. The cause is unknown, and clones differ.$q$, $q$The catalogue does not give a drought score. It warns against high active limestone and the 110 R rootstock.$q$, $q$The Verde Valley AVA FAQ lists Syrah. In the 2016 survey it was the largest share checked, 17.85 acres, 14.3 percent of 124.6 acres. The 2025 University of Arizona harvest report said Syrah led acreage. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. Judge harvest by sugar, acidity, berry and bunch weight, and tasting, not by sugar alone. Wines can be high in alcohol, age-worthy, and aromatic (spices, violet, olive, leather), tannic and robust, with relatively low acidity. pH is sometimes rather high, especially on schist. Color is an intense blue tone. It also makes a fruity rosé.$q$, $q$Trellis the long, wind-fragile shoots. Short pruning is usually enough in southern zones.$q$, $q$Plantgrape Syrah, plantgrape.fr/en/varieties/fruit-varieties/267. Verde Valley AVA FAQ. 2016 Verde Valley vineyard survey. University of Arizona Cooperative Extension, ClimateGem and the 2025 harvest report.$q$),
    (v_id, $q$Vermentino$q$, false, $q$Rather productive and vigorous. Prune short, and train it carefully so the canopy stays in place. Also called Rolle, Garbesso, and Vermentinu. In Italy, Favorita and Pigato. Long grown in Corsica and Provence, and thought to be from Italy.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 7 days after Chasselas. Maturity is mid-season, 3.5 weeks after Chasselas.$q$, $q$Bunches and berries are large.$q$, $q$A little sensitive to grey rot, moderately sensitive to sour rot, and quite sensitive to powdery mildew.$q$, $q$A southern variety, well adapted to hot areas and to dry, not very fertile terroirs.$q$, $q$The Verde Valley AVA FAQ lists Vermentino. The 2016 survey recorded 2.20 acres, 1.8 percent of 124.6 acres. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. The catalogue describes pale, balanced, full whites, aromatic (hawthorn, pear), that sometimes lack acidity.$q$, $q$Short pruning and careful training to hold the canopy.$q$, $q$Plantgrape Vermentino, plantgrape.fr/en/varieties/fruit-varieties/285. Verde Valley AVA FAQ. 2016 Verde Valley vineyard survey. University of Arizona Cooperative Extension ClimateGem.$q$),
    (v_id, $q$Counoise$q$, false, $q$Vigorous and semi-erect. Prune short. It may be grown as a gobelet. Production is irregular because of alternation. Origin is apparently the Vaucluse. Certified clones on the page: 508 and 725.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 11 days after Chasselas. Maturity is mid-season, 3.5 to 4 weeks after Chasselas.$q$, $q$Bunches are medium. Berries are large and sometimes uneven.$q$, $q$Not very sensitive to downy mildew. Fairly susceptible to grey rot.$q$, $q$Particularly suited to warm, stony hillsides. The catalogue does not give a separate drought score.$q$, $q$The 2016 Verde Valley survey listed Counoise with no measurable share of the 124.6 acres. The AVA FAQ list that was checked does not name it. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. The catalogue describes fruity wines with some acidity that are not very colored.$q$, $q$Semi-erect. Short pruning, or gobelet.$q$, $q$Plantgrape Counoise, plantgrape.fr/en/varieties/fruit-varieties/80. 2016 Verde Valley vineyard survey. Verde Valley AVA FAQ. University of Arizona Cooperative Extension ClimateGem.$q$),
    (v_id, $q$Seyval Blanc$q$, false, $q$Vigorous and fertile. An interspecific hybrid, 5656 Seibel × Rayon d'Or (4986 Seibel), officially also 5276 Seyve-Villard. It must be grafted.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 3 days after Chasselas. Maturity is mid-season, 2.5 weeks after Chasselas. Certified clone 1336.$q$, $q$Bunches are small to medium. Berries are small to medium and very bloomed.$q$, $q$Resists downy mildew moderately well and is slightly susceptible to grey rot. Despite those tolerances, a minimum fungicide program is still needed, especially in high-pressure years.$q$, $q$The catalogue does not give a heat or drought score, and this note does not add cold-hardiness numbers from elsewhere.$q$, $q$The Verde Valley AVA FAQ lists Seyval Blanc. The 2016 survey recorded 1.70 acres, 1.4 percent of 124.6 acres. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. The catalogue says Seyval produces wines of acceptable quality.$q$, $q$Prune short or moderately long, and preferably train it.$q$, $q$Plantgrape Seyval, plantgrape.fr/en/varieties/fruit-varieties/263. Verde Valley AVA FAQ. 2016 Verde Valley vineyard survey. University of Arizona Cooperative Extension ClimateGem.$q$),
    (v_id, $q$Petite Sirah$q$, false, $q$Durif, the variety sold as Petite Sirah, is Syrah × Peloursin, developed by Mr Durif. Vigor is low to moderate, and the bearing is semi-erect to horizontal. It is rather fertile and can be pruned short. It is sensitive to winter frosts, and the berries are sensitive to heat and shrivelling. The only certified clone on the page is 1130. A Portugal synonym is Mondet.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 7 days after Chasselas. Maturity is mid-season, 2.5 to 3 weeks after Chasselas (the catalogue prints “2 weeks and a half 3 weeks”).$q$, $q$Bunches and berries are medium.$q$, $q$Sensitive to wood diseases, grey rot, and black rot. Not very susceptible to downy mildew.$q$, $q$Berries are sensitive to heat and shrivelling, and the vine is sensitive to winter frosts. The catalogue does not give a drought score.$q$, $q$The Verde Valley AVA FAQ lists Petite Sirah. In the 2016 survey it was 11.75 acres, 9.4 percent of 124.6 acres. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. Sugar potential is described as average. Wines are colored, fairly tannic and astringent, and not very fruity.$q$, $q$Low to moderate vigor, semi-erect to horizontal. Short pruning is possible.$q$, $q$Plantgrape Durif, plantgrape.fr/en/varieties/fruit-varieties/141. Verde Valley AVA FAQ. 2016 Verde Valley vineyard survey. University of Arizona Cooperative Extension ClimateGem.$q$),
    (v_id, $q$Teroldego$q$, true, $q$The grape's name is Teroldego. The block list spelled it Toraldego. Taraldego is not the name. No vigor note was found. VIVC passport 12371 identifies Teroldego as an Italian black wine grape. That passport is not field performance. No Plantgrape field page was found.$q$, $q$No budbreak or ripening timing was found.$q$, $q$No cluster or berry description was found.$q$, $q$No disease or pest rating was found.$q$, $q$No heat or drought rating was found.$q$, $q$The 2016 Verde Valley survey put Teroldego at about 1 percent of 124.6 acres. The AVA FAQ list that was checked does not name it. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$No published Brix, pH, or titratable acidity was found. This block's own samples are the record.$q$, $q$No canopy note was found.$q$, $q$VIVC 12371 passport only. 2016 Verde Valley vineyard survey. Verde Valley AVA FAQ. University of Arizona Cooperative Extension ClimateGem. Plantgrape index checked, no Teroldego page.$q$),
    (v_id, $q$Syrah 525$q$, false, $q$525 is not on the certified-clone list read on the Plantgrape Syrah page (470, 471, 524, 747, 1140, 1141, 1188, 1345, 1346, 1352, 1353, 1354). In an American Vineyard Foundation trial at Kearney, Parlier, in the San Joaquin Valley, clones 100, 174, 300, and 525 had the lowest soluble solids after two years. That is one hot-valley trial, not an Arizona result. The variety's long shoots are fragile in spring wind and must be trellised. Do not graft on 110 R.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 6 days after Chasselas. Maturity is mid-season, 2.5 weeks after Chasselas. The variety ripens quickly. The Kearney trial is the only 525 timing clue found, and it is not a budbreak date.$q$, $q$In that Kearney trial, 525 had far higher sour-rot incidence, perhaps because of many berries per cluster. Variety bunches are otherwise described as small to medium, with small berries.$q$, $q$The Kearney trial reported far higher sour rot on 525. The variety is not very susceptible to downy mildew, and is rather sensitive to mites and to grey rot late in ripening. Clones differ in the leaf-reddening decline at the graft.$q$, $q$Kearney is a hot San Joaquin Valley site, not the Verde Valley. The variety is poorly adapted to high active limestone.$q$, $q$The variety Syrah led the 2016 Verde Valley survey at 17.85 acres, 14.3 percent, and the 2025 University of Arizona harvest report. This page does not treat the Kearney 525 result as an Arizona result. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. At Kearney, 525 was among the clones with the lowest soluble solids after two years. Judge this block by its own samples, plus sugar, acidity, berry and bunch weight, and tasting.$q$, $q$Trellis the long, wind-fragile shoots. Short pruning is usually enough in southern zones.$q$, $q$Plantgrape Syrah, plantgrape.fr/en/varieties/fruit-varieties/267. American Vineyard Foundation, Kearney clonal trial, avf.org/research-summary/clonal-testing-of-winegrapes-in-the-san-joaquin-valley-2/. University of Arizona Cooperative Extension.$q$),
    (v_id, $q$Syrah 471$q$, false, $q$French certified clone 471 (ENTAV, 1976, Drôme; 12.64 ha of nursery vines) generally shows very few symptoms of decline, has less compact clusters, and reaches good maturity despite the production level. The variety's long shoots are fragile in spring wind and must be trellised. Short pruning is usually enough in southern zones. Do not graft on 110 R.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 6 days after Chasselas. Maturity is mid-season, 2.5 weeks after Chasselas. The clone note says 471 reaches good maturity despite the production level. It does not give a separate budbreak.$q$, $q$This clone has less compact clusters. Variety bunches are small to medium, and berries are small.$q$, $q$The clone generally shows very few symptoms of the Syrah decline (leaf reddening at the graft; trunks can die; cause unknown). The variety is not very susceptible to downy mildew, and is rather sensitive to mites and to grey rot late in ripening.$q$, $q$The catalogue does not give this clone a separate drought score. The variety is poorly adapted to high active limestone. Do not graft it on 110 R.$q$, $q$Syrah led Verde Valley acreage in the 2016 survey (17.85 acres, 14.3 percent) and in the 2025 University of Arizona harvest report. The 471 note itself is from France, not from an Arizona trial. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. The only clone-specific maturity line found is that 471 reaches good maturity despite its production level. Judge the block by sugar, acidity, berry and bunch weight, and tasting.$q$, $q$Trellis the long, wind-fragile shoots. The clone note does not change that.$q$, $q$Plantgrape Syrah, plantgrape.fr/en/varieties/fruit-varieties/267. ENTAV clone 471, selections.entav-inra.fr/en/clones/471. Verde Valley AVA FAQ. University of Arizona Cooperative Extension.$q$),
    (v_id, $q$Grenache$q$, false, $q$Very vigorous, with strong trunks. It can have coulure and trouble lignifying. The bearing is erect. Prune short, as a gobelet or a cordon. Magnesium deficiency is easy to provoke. Origin is Spain; grown in France since the Middle Ages. Garnacha Tinta is a synonym.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 5 days after Chasselas. Maturity is late, 4 weeks after Chasselas.$q$, $q$Bunches are medium to large. Berries are medium.$q$, $q$Very sensitive to downy mildew and phomopsis. Rather sensitive to bacterial necrosis, grey rot, and vine moths. Not very susceptible to mites. Ungrafted vines resist the nematode Meloidogyne arenaria in coastal sands.$q$, $q$Better on slightly acid gravel or stony ground than on very limestone white soil. The catalogue does not give a separate drought score.$q$, $q$Grenache was 3.80 acres, 3.0 percent, in the 2016 Verde Valley survey. The 2025 University of Arizona harvest report ranked it second in acreage after Syrah. The AVA FAQ list that was checked does not name Grenache. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. The catalogue says sugar potential is very high, color drops quickly as yield rises, and acidity is generally low.$q$, $q$Erect. Short pruning on gobelet or cordon.$q$, $q$Plantgrape Grenache, plantgrape.fr/en/varieties/fruit-varieties/120. 2016 Verde Valley vineyard survey. University of Arizona Cooperative Extension, ClimateGem and the 2025 harvest report. Verde Valley AVA FAQ.$q$),
    (v_id, $q$Merlot$q$, false, $q$Moderately to strongly vigorous. It tends to make many offshoots and suckers. The bearing is semi-erect to horizontal and needs enough trellising. Fertility is good, and it is better pruned short. Coulure is a risk in some climates. From Bordeaux. Published genetics: Cabernet franc × Magdeleine noire.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 2 days after Chasselas. Maturity is mid-season, 2.5 weeks after Chasselas (the catalogue prints “2 weeks and a half”).$q$, $q$Bunches are small to medium and winged. Berries are medium.$q$, $q$Particularly sensitive to downy mildew on flowers and bunches, to vine leafhoppers, and to burls (the catalogue's word). Rather sensitive to grey rot. Not very susceptible to powdery mildew, flavescence dorée, or wood diseases.$q$, $q$Well suited to clay-limestone soils. Rather sensitive to winter and spring frosts because budburst is early. Not very adapted to intense drought.$q$, $q$The Verde Valley AVA FAQ list that was checked does not name Merlot, and the 2016 shares that were checked did not give a Merlot acreage. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. The catalogue describes round, powerful, colored wines, rich in alcohol, with relatively low acidity, full body, and rather supple tannins.$q$, $q$Give the semi-erect to horizontal shoots enough trellis. Short pruning is preferred.$q$, $q$Plantgrape Merlot, plantgrape.fr/en/varieties/fruit-varieties/164. Verde Valley AVA FAQ. University of Arizona Cooperative Extension ClimateGem.$q$),
    (v_id, $q$Viognier$q$, false, $q$Usually trained, sometimes sensitive to wind, pruned moderately long, at a fairly high planting density. A native of the northern Côtes du Rhône. Analyses at Montpellier found it closely related to Mondeuse blanche.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is the same day as Chasselas. Maturity is mid-season, 2.5 weeks after Chasselas (the catalogue prints “2 weeks and a half”).$q$, $q$Bunches are small and compact. Berries are small.$q$, $q$The catalogue says it does not seem particularly sensitive to diseases.$q$, $q$Traditionally grown on acidic terroirs. Well adapted to sufficiently deep, not too fertile soils in southern areas, to avoid drought. Early budburst exposes it to spring frosts.$q$, $q$The Verde Valley AVA FAQ lists Viognier. The 2025 University of Arizona harvest report included it among six varieties that were half of 532 acres. A separate 2016 acreage was not in the shares checked. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. The catalogue says the sugar accumulation potential is high. The wines are full-bodied but a bit low in acidity, sometimes with a slight bitterness. Aromas it names include apricot (the page prints abricot) and peach.$q$, $q$Train it, with moderately long pruning. The catalogue notes wind sensitivity.$q$, $q$Plantgrape Viognier, plantgrape.fr/en/varieties/fruit-varieties/288. Verde Valley AVA FAQ. University of Arizona Cooperative Extension, ClimateGem and the 2025 harvest report.$q$),
    (v_id, $q$Mourvèdre$q$, false, $q$Demanding and delicate to grow. Erect and acrotonic, so prune it short: cordon, reduced trellis, or open gobelet. The foliage is not abundant and is only moderately effective. Avoid trimming, which encourages large shot clusters that compete. Keep the crop per vine low or the vine can deplete. Fertility can alternate. From Spain, probably in France since the end of the Middle Ages. Official synonyms include Mataro and Monastrell.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 14 days after Chasselas. Maturity is late, 4.5 weeks after Chasselas (the catalogue prints “4 weeks and a half”).$q$, $q$Bunches are medium to large. Berries are medium.$q$, $q$Sensitive to mites, vine leafhoppers, esca, and sour rot. Not very susceptible to grey rot. It resists phomopsis well.$q$, $q$Needs limestone soils deep enough for a limited but regular water supply, and a balanced potassium-to-magnesium supply. Ripening needs very high temperatures, especially high night temperatures. The catalogue reserves it for the hottest, best-exposed southern sites.$q$, $q$The AVA FAQ list that was checked does not name Mourvèdre, and the 2016 shares that were checked did not give it an acreage. The catalogue reserves it for the hottest sites. That is a requirement to check on this ranch, not a claim that it is already planted here. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. The catalogue's own bar is sufficient maturity, stated as 12 natural degrees minimum, and a limited crop per vine. Color potential is moderate and acidity can be lacking. When those conditions are met it describes aromatic, tannic, structured wines that can age and take wood.$q$, $q$Short pruning on cordon, reduced trellis, or open gobelet. Do not trim hard. Keep the modest canopy.$q$, $q$Plantgrape Mourvèdre, plantgrape.fr/en/varieties/fruit-varieties/177. Verde Valley AVA FAQ. University of Arizona Cooperative Extension ClimateGem.$q$),
    (v_id, $q$Chardonnay$q$, false, $q$Generally pruned long. Where flowering is reliable it may be pruned short. Suited to moderately fertile limestone or marl soils. From Burgundy. Published genetics: Pinot × Gouais blanc.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 1 day before Chasselas. Maturity is early, 1.5 weeks after Chasselas (the catalogue prints “1 week and a half”).$q$, $q$Bunches and berries are small.$q$, $q$Susceptible to powdery mildew, and it strongly expresses grapevine yellows. Under strong vigor, grey rot can do real damage at the end of ripening.$q$, $q$In Mediterranean areas the catalogue says to avoid intense drought.$q$, $q$The Verde Valley AVA FAQ lists Chardonnay. The 2025 University of Arizona harvest report included it among six varieties that were half of 532 acres. A separate 2016 acreage was not in the shares checked. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. The catalogue says sugar can reach high levels while acidity stays high, which is what makes the wines balanced, powerful, and ample. It is used for dry whites, sparkling wines, and liqueur wines, and it suits barrel fermentation and ageing.$q$, $q$Long pruning is the usual choice. Short pruning is possible where fruitfulness is reliable.$q$, $q$Plantgrape Chardonnay, plantgrape.fr/en/varieties/fruit-varieties/60. Verde Valley AVA FAQ. University of Arizona Cooperative Extension, ClimateGem and the 2025 harvest report.$q$),
    (v_id, $q$Sangiovese$q$, false, $q$The French catalogue lists this Tuscan variety as Nielluccio (also Niellucciu; in Italy, Sangiovese and Prugnolo gentile). Moderate vigor and an early budburst. Prune short, as a gobelet or a cordon.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is the same day as Chasselas. Maturity is mid-season, 3.5 weeks after Chasselas (the catalogue prints “3 weeks and a half”).$q$, $q$Bunches are medium. Berries are large.$q$, $q$Susceptible to flavescence dorée. Moderately susceptible to powdery mildew. Not very sensitive to grey rot.$q$, $q$Resists drought well and appears adapted to low-fertility soils.$q$, $q$The Verde Valley AVA FAQ lists Sangiovese. The 2025 University of Arizona harvest report notes the Verde Valley for minor and Italian varieties, including Sangiovese. A separate 2016 acreage was not in the shares checked. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. The catalogue describes full-bodied, fruity wines that move toward spice, with finesse and balance, suited to ageing. Color decreases as yield rises. It also makes rosé.$q$, $q$Short pruning on gobelet or cordon.$q$, $q$Plantgrape Nielluccio (Sangiovese), plantgrape.fr/en/varieties/fruit-varieties/192. Verde Valley AVA FAQ. University of Arizona Cooperative Extension 2025 harvest report and ClimateGem.$q$),
    (v_id, $q$Barbera$q$, false, $q$Vigorous, semi-erect, with regular fertility. It can overcrop if vigor is not managed. Prune long and trellis the long shoots. From northern Italy (Piedmont). In some cases it is sensitive to potassium deficiency.$q$, $q$At Domaine de Vassal on the Mediterranean coast (Chasselas budburst 17 March and maturity 12 August, 70-year average; not an Arizona date), budburst is 1 day after Chasselas. Maturity is mid-season, 3.5 weeks after Chasselas (the catalogue prints “3 weeks and a half”).$q$, $q$Bunches are medium and compact, with a particularly long peduncle that stays green or barely lignified. Berries are medium, with bloom, a moderately thick skin, and juicy pulp.$q$, $q$A little sensitive to downy mildew. Very sensitive to grey rot and sour rot. Often affected by grapevine leafroll-associated virus and, in California, by Pierce's disease.$q$, $q$Adapted to clay-limestone soils that are dry and not very fertile.$q$, $q$The Verde Valley AVA FAQ lists Barbera. The 2025 University of Arizona harvest report names it among Italian varieties in the Verde Valley. A separate 2016 acreage was not in the shares checked. Almost all of the Verde Valley AVA has a growing-season temperature (1 April–31 October, 1981–2010) of 70–75°F (21–24°C), University of Arizona Cooperative Extension ClimateGem.$q$, $q$The catalogue does not publish a target Brix, pH, or titratable acidity. This block's own samples are the record. The catalogue says the fruit keeps a high acidity when ripe. It is used for sparkling wines, new wines, and, when riper, barrel-aged reds that are colored, rich, and generous.$q$, $q$Long pruning and a trellis for the long shoots. Hold the vigor back or the crop gets large.$q$, $q$Plantgrape Barbera, plantgrape.fr/en/varieties/fruit-varieties/337. Verde Valley AVA FAQ. University of Arizona Cooperative Extension, ClimateGem and the 2025 harvest report.$q$)
  on conflict (vineyard_id, variety) do nothing;

end $seed$;
